fix.patch:
--- a/src/refund.ts
+++ b/src/refund.ts
@@ -1,4 +1,8 @@
 export function refund(order: { captured: number }, amount: number) {
-  // BUG: amount is never checked against the captured amount
-  return { refunded: amount };
+  if (!Number.isFinite(amount) || amount <= 0) {
+    throw new RangeError('refund amount must be a positive finite number');
+  }
+  if (amount > order.captured) {
+    throw new RangeError('refund amount exceeds captured amount');
+  }
+  return { refunded: amount };
 }

